// Skia's configuration for Andruna's guest build (aosp/modules/skia.cmake).
//
// Android's build includes external/skia/android/include/config/SkUserConfig.h,
// generated by gn_to_bp.py. This file takes its place (its directory comes
// first on the include path) and keeps every define of that file except the
// features whose dependencies Andruna does not build yet:
//
//   SK_VULKAN                           libvulkan (HWUI uses the GL pipeline)
//   SK_CODEC_DECODES_AVIF               libcrabbyavif_ffi (Rust)
//   SK_CODEC_DECODES_RAW                libdng_sdk and libpiex
//   SK_FONTMGR_FONTATIONS_AVAILABLE,
//   SK_TYPEFACE_FACTORY_FONTATIONS      libskrifa (Rust); FreeType is used
//   SK_ANDROID_FRAMEWORK_USE_PERFETTO   libperfetto_client_experimental
//
// The values of the remaining defines are the generated file's.
#pragma once
#include "SkUserConfigManual.h"

#define SK_CODEC_DECODES_BMP
#define SK_CODEC_DECODES_GIF
#define SK_CODEC_DECODES_ICO
#define SK_CODEC_DECODES_JPEG
#define SK_CODEC_DECODES_JPEG_GAINMAPS
#define SK_CODEC_DECODES_PNG
#define SK_CODEC_DECODES_PNG_WITH_LIBPNG
#define SK_CODEC_DECODES_WBMP
#define SK_CODEC_DECODES_WEBP
#define SK_CODEC_ENCODES_JPEG
#define SK_CODEC_ENCODES_PNG
#define SK_CODEC_ENCODES_PNG_WITH_LIBPNG
#define SK_CODEC_ENCODES_WEBP
#define SK_ENABLE_ANDROID_UTILS
#if defined(__x86_64__)
#define SK_ENABLE_AVX512_OPTS
#endif
#define SK_ENABLE_PRECOMPILE
#define SK_FONTMGR_FREETYPE_EMPTY_AVAILABLE
#define SK_GAMMA_APPLY_TO_A8
#define SK_GAMMA_CONTRAST 0.0
#define SK_GAMMA_EXPONENT 1.4
#define SK_GANESH
#define SK_GL
#define SK_HAS_WUFFS_LIBRARY
#define SK_SUPPORT_PDF
#define SK_TYPEFACE_FACTORY_FREETYPE
#define SK_XML

#ifndef SK_BUILD_FOR_ANDROID
    #error "SK_BUILD_FOR_ANDROID must be defined!"
#endif
#if defined(SK_BUILD_FOR_IOS) || defined(SK_BUILD_FOR_MAC) || \
    defined(SK_BUILD_FOR_UNIX) || defined(SK_BUILD_FOR_WIN)
    #error "Only SK_BUILD_FOR_ANDROID should be defined!"
#endif
